import { Component } from '@angular/core';
import { BillsTable } from './bills-table/bills-table';
import { HttpClientModule } from '@angular/common/http';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [BillsTable, HttpClientModule],
  template: `
    <div class="app-container">
      <header class="app-header">
        <h1>Credit Bills Management</h1>
        <p>Manage your credit bills with ease</p>
      </header>
      <main class="app-main">
        <app-bills-table></app-bills-table>
      </main>
    </div>
  `,
  styles: [`
    .app-container {
      min-height: 100vh;
      background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
      padding: 2rem;
    }

    .app-header {
      text-align: center;
      color: white;
      margin-bottom: 2rem;
    }

    .app-header h1 {
      font-size: 2.5rem;
      margin: 0 0 0.5rem 0;
      font-weight: 600;
    }

    .app-header p {
      font-size: 1.2rem;
      margin: 0;
      opacity: 0.9;
    }

    .app-main {
      max-width: 1200px;
      margin: 0 auto;
    }

    @media (max-width: 768px) {
      .app-container {
        padding: 1rem;
      }
      
      .app-header h1 {
        font-size: 2rem;
      }
      
      .app-header p {
        font-size: 1rem;
      }
    }
  `]
})
export class AppComponent {
  title = 'Credit Bills Management';
}